const canvas = document.getElementById('myCanvas');
const ctx = canvas.getContext('2d');

// 1. Get the device pixel ratio (usually 2 for Retina/High-DPI)
const dpr = window.devicePixelRatio || 1;

// 2. Get the intended logical size (from CSS or layout)
const logicalWidth = 500; 
const logicalHeight = 300;

// 3. Set the internal drawing buffer to the physical resolution
